// Flush persists the in-memory map to disk.
func (s *Store) Flush() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.path == ":memory:" {
		return nil
	}
	b, err := json.Marshal(s.data)
	if err != nil {
		return err
	}
	return os.WriteFile(s.path, b, 0o600)
}

// Close flushes the store to disk.
func (s *Store) Close() error {
	return s.Flush()
}

